            if (document.activeElement) {
                document.activeElement.blur();
            }

            // \u76F4\u63A5\u5220\u9664\uFF0C\u4E0D\u4F7F\u7528 confirm\uFF08iOS WebView \u4E0D\u652F\u6301\uFF09
